{
  "findings": [
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "A parent reports that children under 13 can use Roblox if a parent creates a linked account and enables parental controls.",
      "stance": "neutral",
      "quote": "Users ages 5 and older may create an Account, but certain features for the Services must be enabled by a parent or legal guardian through our Parental Controls."
    },
    {
      "ref": "[D502]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child unless parental controls are turned on.",
      "stance": "risk",
      "quote": "If you use Roblox Studio, Creator Store, Creator Hub, DevForum, Roblox APIs or other Developer Products, services, or associated software (collectively, “Roblox Creator Platform”), the Creator Terms of Use (“Creator Terms”) also apply to that use."
    },
    {
      "ref": "[D502]",
      "area": "money",
      "claim": "A parent reports that the app pushes in‑app purchases and loot‑box style mechanics that can lead to unintended spending.",
      "stance": "risk",
      "quote": "You may be able to use Robux to acquire Roblox Marketplace Items. Any use of Robux shall be subject to the terms and conditions of Section 5.1 below."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data such as email, phone number, and birthdate, and may share it for advertising.",
      "stance": "risk",
      "quote": "You may be asked to provide information like an email address, phone number, or a government‑issued photo identification to access certain Content or features in Roblox Player."
    },
    {
      "ref": "[D502]",
      "area": "content",
      "claim": "A parent reports that the platform hosts user‑generated items that can include inappropriate clothing or accessories.",
      "stance": "risk",
      "quote": "Our Services may display UGC created by other Users for use with your avatar, such as clothing, accessories, or other digital items (“User Marketplace Items”)."
    },
    {
      "ref": "[D502]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory fines for violating child‑privacy rules.",
      "stance": "risk",
      "quote": "Roblox may block, remove, or delete Content in certain regions for legal and regulatory reasons, such as an order or injunction from any court, administrative body, or regulatory authority."
    }
  ]
}
